	@Test
	void cleanupFailurePreventsResizeConflictReplay() {
		LmdbSailStore.MapResizeConflictException resizeConflict = new LmdbSailStore.MapResizeConflictException(
				LmdbSailStore.MapResizeKind.TRIPLE_STORE, "test resize conflict");
		RuntimeException replaySignal = assertThrows(QueryExecutionContext.ReplaySafepointException.class, () -> {
			try (QueryExecutionContext.Activation ignored = QueryExecutionContext.activateReplaySafepoint(
					() -> {
						throw resizeConflict;
					})) {
				QueryExecutionContext.checkpointReplaySafepoint();
			}
		});
		replaySignal.addSuppressed(new IllegalStateException("the returned result could not be closed"));

		assertTrue(QueryExecutionContext.isReplaySafepointFailure(replaySignal));
		assertTrue(LmdbStoreConnection.isMapResizeConflict(resizeConflict));
		assertFalse(LmdbStoreConnection.isMapResizeConflict(replaySignal),
				"transparent replay must not discard a failure to release the abandoned result");
	}

	@Test
	void mapGrowthLeavesTheEstimatedWriteAndReserveBelowTheEightyPercentThreshold() {
		long pageSize = 4096L;
		long currentMapSize = 1024L * 1024L;
		long estimatedUsedBytesAfterWrite = 16L * LmdbUtil.MIN_FREE_SPACE;

		long grownMapSize = LmdbUtil.autoGrowMapSize(currentMapSize, pageSize, estimatedUsedBytesAfterWrite);
		long estimatedWithReserve = estimatedUsedBytesAfterWrite + LmdbUtil.MIN_FREE_SPACE;

		assertEquals(0L, grownMapSize % pageSize, "the final map size must align to the native page size");
		assertTrue(estimatedWithReserve * 100L < grownMapSize * LmdbUtil.PERCENTAGE_FULL_TRIGGERS_RESIZE,
				"the predicted write and recent-allocation reserve must remain below the resize threshold");
	}

	@Test
	void namespacePreflightEstimatesTheCompleteResultingSnapshot() throws Exception {
		Map<String, String> existingNamespaces = new LinkedHashMap<>();
		for (int index = 0; index < 512; index++) {
			existingNamespaces.put("prefix-" + index + "-ø", "https://example.org/" + "語".repeat(96) + index);
		}

		String replacedPrefix = "prefix-0-ø";
		String replacementNamespace = "https://example.net/" + "雪".repeat(128);
		Map<String, String> resultingNamespaces = new LinkedHashMap<>(existingNamespaces);
		resultingNamespaces.put(replacedPrefix, replacementNamespace);
		SailSource.WritePreflight preflight = new SailSource.WritePreflight(List.of(),
				List.of(new SailSource.NamespaceUpdate(replacedPrefix, replacementNamespace)), Set.of(), Set.of(),
				false,
				false);

		TripleStore tripleStore = mock(TripleStore.class);
		when(tripleStore.readNamespaceSnapshot()).thenReturn(existingNamespaces);
		when(tripleStore.estimateWriteBytes(anyList())).thenReturn(0L);
		doCallRealMethod().when(tripleStore).estimateWriteBytes(any(SailSource.WritePreflight.class));
		NamespaceStore namespaceStore = new NamespaceStore(new File("unused"), tripleStore);

		long estimatedWriteBytes = LmdbUtil.saturatedAdd(tripleStore.estimateWriteBytes(preflight),
				namespaceStore.estimateEncodedSnapshotBytes(preflight));
		long encodedSnapshotBytes = NamespaceStore.encodeSnapshot(resultingNamespaces).length;
		assertTrue(estimatedWriteBytes >= encodedSnapshotBytes,
				"preflight must include the complete encoded namespace snapshot, not only the updated prefix");

		SailSource.WritePreflight removal = new SailSource.WritePreflight(List.of(), List.of(), Set.of(replacedPrefix),
				Set.of(), false, false);
		Map<String, String> afterRemoval = new LinkedHashMap<>(existingNamespaces);
		afterRemoval.remove(replacedPrefix);
		assertTrue(
				namespaceStore
						.estimateEncodedSnapshotBytes(removal) >= NamespaceStore.encodeSnapshot(afterRemoval).length,
				"removal preflight may overestimate, but must cover the resulting snapshot");

		SailSource.NamespaceUpdate clearedUpdate = new SailSource.NamespaceUpdate("清除", "urn:雪");
		SailSource.WritePreflight clearAndAdd = new SailSource.WritePreflight(List.of(), List.of(clearedUpdate),
				Set.of(),
				Set.of(), false, true);
		Map<String, String> afterClear = Map.of(clearedUpdate.prefix(), clearedUpdate.name());
		assertTrue(
				namespaceStore
						.estimateEncodedSnapshotBytes(clearAndAdd) >= NamespaceStore.encodeSnapshot(afterClear).length,
				"clear and replacement namespace intents must size the post-clear snapshot");

		SailSource.WritePreflight explicit = new SailSource.WritePreflight(List.of(),
				List.of(new SailSource.NamespaceUpdate("explicit", "urn:explicit")), Set.of(), Set.of(), false, false);
		SailSource.WritePreflight inferred = new SailSource.WritePreflight(List.of(),
				List.of(new SailSource.NamespaceUpdate("inferred", "urn:inferred")), Set.of(), Set.of(), false, false);
		SailSource.WritePreflight merged = explicit.merge(inferred);
		Map<String, String> afterMerged = new LinkedHashMap<>(existingNamespaces);
		afterMerged.put("explicit", "urn:explicit");
		afterMerged.put("inferred", "urn:inferred");
		assertTrue(
				namespaceStore
						.estimateEncodedSnapshotBytes(merged) >= NamespaceStore.encodeSnapshot(afterMerged).length,
				"merged explicit and inferred namespace updates must both be included");

		SailSource.WritePreflight statementsOnly = new SailSource.WritePreflight(List.of(), List.of(), Set.of(),
				Set.of(),
				false, false);
		assertEquals(0L, namespaceStore.estimateEncodedSnapshotBytes(statementsOnly),
				"ordinary statement-only writes must not pay for namespace snapshot growth");

		namespaceStore.setNamespace("later", "urn:後");
		assertEquals(NamespaceStore.encodeSnapshot(namespaceStore.snapshot()).length,
				namespaceStore.estimateEncodedSnapshotBytes(removal),
				"adding a namespace must update the cached base snapshot size");
		namespaceStore.setNamespace("later", "urn:改訂");
		assertEquals(NamespaceStore.encodeSnapshot(namespaceStore.snapshot()).length,
				namespaceStore.estimateEncodedSnapshotBytes(removal),
				"replacing a namespace must update the cached encoded size");
		namespaceStore.removeNamespace("later");
		assertEquals(NamespaceStore.encodeSnapshot(namespaceStore.snapshot()).length,
				namespaceStore.estimateEncodedSnapshotBytes(removal),
				"removing a namespace must update the cached encoded size");
		namespaceStore.clear();
		assertEquals(Integer.BYTES, NamespaceStore.encodeSnapshot(namespaceStore.snapshot()).length);
		assertEquals(Integer.BYTES, namespaceStore.estimateEncodedSnapshotBytes(removal),
				"clearing the namespace map must reset the cached encoded size to its header");
		namespaceStore.restore(existingNamespaces);
		assertEquals(NamespaceStore.encodeSnapshot(existingNamespaces).length,
				namespaceStore.estimateEncodedSnapshotBytes(removal),
				"restoring a namespace snapshot must restore its cached encoded size");
	}

	@Test
	void bufferedWholeWritePreflightGrowsBothMapsBeforeBranchPreparation(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 64L)
				.setValueDBSize(4096L * 64L)
				.setMapGrowthReadDrainTimeoutMillis(0);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			long initialTripleMapSize = mapSize(backingStore, "tripleStore");
			long initialValueMapSize = mapSize(backingStore, "valueStore");

			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				for (int index = 0; index < 10_000; index++) {
					connection.add(VF.createIRI("urn:growth-subject:" + index),
							VF.createIRI("urn:growth-predicate"),
							VF.createLiteral("growth-object:" + index));
				}

				connection.prepare();

				assertTrue(mapSize(backingStore, "tripleStore") > initialTripleMapSize,
						"preparing the complete buffered branch write must grow the TripleStore map first");
				assertTrue(mapSize(backingStore, "valueStore") > initialValueMapSize,
						"preparing the complete buffered branch write must grow the ValueStore map first");
				connection.rollback();
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(value = 10, unit = TimeUnit.SECONDS)
	void bufferedGrowthWarningBeginsBeforeExplicitPrepareAndRollbackClosesTheEpisode(@TempDir File dataDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 64L)
				.setValueDBSize(4096L * 64L)
				.setMapGrowthReadDrainTimeoutMillis(30_000);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			long initialTripleMapSize = mapSize(backingStore, "tripleStore");
			long initialValueMapSize = mapSize(backingStore, "valueStore");
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				for (int index = 0; index < 10_000; index++) {
					connection.add(VF.createIRI("urn:early-growth-subject:" + index),
							VF.createIRI("urn:early-growth-predicate"),
							VF.createLiteral("early-growth-object:" + index));
				}

				assertTrue(backingStore.growthAdmissionClosed(),
						"buffering a write beyond the warning threshold must close admission and start growth before prepare");
				assertEquals(initialTripleMapSize, mapSize(backingStore, "tripleStore"),
						"the early warning must not resize the TripleStore before validation and preflight");
				assertEquals(initialValueMapSize, mapSize(backingStore, "valueStore"),
						"the early warning must not resize the ValueStore before validation and preflight");
				ExecutorService arrivalExecutor = Executors.newSingleThreadExecutor();
				Future<Boolean> arrival;
				try {
					arrival = arrivalExecutor.submit(() -> {
						try (RepositoryConnection arrivingReader = repository.getConnection()) {
							return arrivingReader.getStatements(null, null, null).hasNext();
						}
					});
					awaitCurrentAdmissionWaiter(backingStore);
					assertTrue(backingStore.growthMetricsSnapshot().currentAdmissionWaiters() > 0,
							"a read arriving after the warning must wait for the writer's shared growth episode");
					connection.rollback();
					assertFalse(arrival.get(5, TimeUnit.SECONDS),
							"the arriving read must continue after the buffered writer rolls back");
				} finally {
					arrivalExecutor.shutdownNow();
					assertTrue(arrivalExecutor.awaitTermination(5, TimeUnit.SECONDS),
							"admission-wait test worker must terminate");
				}
				assertEquals(0, backingStore.growthMetricsSnapshot().currentAdmissionWaiters(),
						"rollback must release every blocked admission");
				assertFalse(backingStore.growthAdmissionClosed(), "rollback must close the growth episode");
			}
		} finally {
			repository.shutDown();
		}
	}

