	@Test
	@Timeout(value = 8, unit = TimeUnit.SECONDS)
	void laterWriteRenewsWarningWithoutAnInterveningAdmissionProbe(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 64L)
				.setValueDBSize(4096L * 64L)
				.setMapGrowthReadDrainTimeoutMillis(250);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (RepositoryConnection writer = repository.getConnection()) {
			writer.begin();
			writer.add(VF.createIRI("urn:warning-no-probe:subject:1"),
					VF.createIRI("urn:warning-no-probe:predicate"), VF.createLiteral("x".repeat(1024 * 1024)));

			// Let the bounded warning expire without querying coordinator admission or metrics, both of which perform
			// lazy expiry as a side effect.
			TimeUnit.MILLISECONDS.sleep(350);

			writer.add(VF.createIRI("urn:warning-no-probe:subject:2"),
					VF.createIRI("urn:warning-no-probe:predicate"), VF.createLiteral("y".repeat(1024 * 1024)));
			assertTrue(store.getBackingStore().growthAdmissionClosed(),
					"the later write must start a fresh warning even when no reader probes admission after expiry");
			writer.rollback();
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void connectionsOnTheSameThreadKeepDistinctWarningOwners(@TempDir File dataDir) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 64L)
				.setValueDBSize(4096L * 64L)
				.setMapGrowthReadDrainTimeoutMillis(2_000);
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			LmdbSailStore backingStore = store.getBackingStore();
			try (RepositoryConnection firstWriter = repository.getConnection();
					RepositoryConnection secondWriter = repository.getConnection()) {
				firstWriter.begin();
				secondWriter.begin();
				firstWriter.add(VF.createIRI("urn:warning-owner:first"), VF.createIRI("urn:warning-owner:predicate"),
						VF.createLiteral("x".repeat(1024 * 1024)));
				assertTrue(backingStore.growthAdmissionClosed(),
						"the first connection must start its warning before the second writer buffers data");

				long startNanos = System.nanoTime();
				secondWriter.add(VF.createIRI("urn:warning-owner:second"),
						VF.createIRI("urn:warning-owner:predicate"), VF.createLiteral("y".repeat(1024 * 1024)));
				long elapsedMillis = TimeUnit.NANOSECONDS.toMillis(System.nanoTime() - startNanos);
				assertTrue(elapsedMillis < 1_500,
						"a second connection on the same thread must not be mistaken for the first writer until warning expiry");
				secondWriter.rollback();
				firstWriter.rollback();
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void sameThreadExplicitWriterPromotesItsWarningBeforeTheDefaultDrainDeadline(@TempDir File dataDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 64L)
				.setValueDBSize(4096L * 64L);
		assertEquals(5_000L, config.getMapGrowthReadDrainTimeoutMillis());
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		ExecutorService writerExecutor = Executors.newSingleThreadExecutor();
		try {
			Future<?> preparation = writerExecutor.submit(() -> {
				try (RepositoryConnection writer = repository.getConnection()) {
					writer.begin();
					writer.add(VF.createIRI("urn:warning-owner:same-thread"),
							VF.createIRI("urn:warning-owner:predicate"),
							VF.createLiteral("x".repeat(1024 * 1024)));
					assertTrue(store.getBackingStore().growthAdmissionClosed(),
							"the explicit transaction must begin a warning while buffering its write");
					writer.prepare();
					writer.rollback();
				}
			});
			assertCompletesPromptly(preparation,
					"preparing on the buffering thread must promote that writer's existing warning");
		} finally {
			writerExecutor.shutdownNow();
			boolean writerTerminated = writerExecutor.awaitTermination(5, TimeUnit.SECONDS);
			repository.shutDown();
			assertTrue(writerTerminated, "the cancellable writer worker must terminate");
		}
	}

	@Test
	@Timeout(value = 15, unit = TimeUnit.SECONDS)
	void handedOffExplicitWriterPromotesItsWarningBeforeTheDefaultDrainDeadline(@TempDir File dataDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(4096L * 64L)
				.setValueDBSize(4096L * 64L);
		assertEquals(5_000L, config.getMapGrowthReadDrainTimeoutMillis());
		LmdbStore store = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(store);
		repository.init();
		ExecutorService bufferExecutor = Executors.newSingleThreadExecutor();
		ExecutorService prepareExecutor = Executors.newSingleThreadExecutor();
		try {
			AtomicReference<Thread> bufferingThread = new AtomicReference<>();
			Future<RepositoryConnection> bufferedConnection = bufferExecutor.submit(() -> {
				bufferingThread.set(Thread.currentThread());
				RepositoryConnection writer = repository.getConnection();
				boolean handedOff = false;
				try {
					writer.begin();
					writer.add(VF.createIRI("urn:warning-owner:thread-handoff"),
							VF.createIRI("urn:warning-owner:predicate"),
							VF.createLiteral("x".repeat(1024 * 1024)));
					assertTrue(store.getBackingStore().growthAdmissionClosed(),
							"the explicit transaction must begin a warning while buffering its write");
					handedOff = true;
					return writer;
				} finally {
					if (!handedOff) {
						writer.close();
					}
				}
			});
			RepositoryConnection writer = bufferedConnection.get(5, TimeUnit.SECONDS);
			bufferExecutor.shutdown();
			assertTrue(bufferExecutor.awaitTermination(5, TimeUnit.SECONDS),
					"the buffering thread must finish before the sequential handoff");

			Future<?> preparation = prepareExecutor.submit(() -> {
				assertFalse(Thread.currentThread() == bufferingThread.get(),
						"prepare must run on a different thread from the buffering operation");
				try (writer) {
					writer.prepare();
					writer.rollback();
				}
			});
			assertCompletesPromptly(preparation,
					"a sequential thread handoff must preserve the explicit writer's warning ownership");
		} finally {
			bufferExecutor.shutdownNow();
			prepareExecutor.shutdownNow();
			boolean bufferTerminated = bufferExecutor.awaitTermination(5, TimeUnit.SECONDS);
			boolean prepareTerminated = prepareExecutor.awaitTermination(5, TimeUnit.SECONDS);
			repository.shutDown();
			assertTrue(bufferTerminated, "the buffer worker must terminate");
			assertTrue(prepareTerminated, "the cancellable prepare worker must terminate");
		}
	}

	private static void assertCompletesPromptly(Future<?> operation, String failureMessage) throws Exception {
		try {
			operation.get(5, TimeUnit.SECONDS);
		} catch (TimeoutException timeout) {
			operation.cancel(true);
			throw new AssertionError(failureMessage, timeout);
		}
	}

	private static void awaitCurrentAdmissionWaiter(LmdbSailStore store) throws InterruptedException {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (store.growthMetricsSnapshot().currentAdmissionWaiters() == 0) {
			if (System.nanoTime() >= deadlineNanos) {
				throw new AssertionError("No reader entered the closed map-growth admission gate");
			}
			TimeUnit.MILLISECONDS.sleep(1);
		}
	}

	private static void awaitGrowthAdmissionOpen(LmdbSailStore store) throws InterruptedException {
		long deadlineNanos = System.nanoTime() + TimeUnit.SECONDS.toNanos(3);
		while (store.growthAdmissionClosed()) {
			if (System.nanoTime() >= deadlineNanos) {
				throw new AssertionError("The expired buffered warning did not reopen admission");
			}
			TimeUnit.MILLISECONDS.sleep(1);
		}
	}

	private static long mapSize(LmdbSailStore backingStore, String storeFieldName) throws ReflectiveOperationException {
		Field storeField = LmdbSailStore.class.getDeclaredField(storeFieldName);
		storeField.setAccessible(true);
		Object mapStore = storeField.get(backingStore);
		Field mapSizeField = mapStore.getClass().getDeclaredField("mapSize");
		mapSizeField.setAccessible(true);
		return mapSizeField.getLong(mapStore);
	}
